// Simon Tatham's linked list merge sort algorithm
// http://www.chiark.greenend.org.uk/~sgtatham/algorithms/listsort.html
assert(list);
Node* p;
Node* q;
Node* e;
Node* tail;
int i, numMerges, pSize, qSize;
int inSize = 1;

for (;;) {
    p = list;
    list = nullptr;
    tail = nullptr;
    numMerges = 0;

    while (p) {
        numMerges++;
        q = p;
        pSize = 0;
        for (i = 0; i < inSize; i++) {
            pSize++;
            q = q->nextZ;
            if (!q) break;
        }

        qSize = inSize;

        while (pSize > 0 || (qSize > 0 && q)) {

            if (pSize == 0) {
                e = q;
                q = q->nextZ;
                qSize--;
            } else if (qSize == 0 || !q) {
                e = p;
                p = p->nextZ;
                pSize--;
            } else if (p->z <= q->z) {
