// ===== VARIANT B (NEW: earcut.hpp 2.2.3/2.2.4, JS 2.2.3+) — *** THIS IS THE REFERENCE *** =====
Node* eliminateHole(Node* hole, Node* outerNode) {
    Node* bridge = findHoleBridge(hole, outerNode);
    if (!bridge) {
