```
Key = (min x, then min y); both strict `<`, so an exact duplicate loses to the earlier-visited node.

### 1.18 `findHoleBridge`

```
Node* findHoleBridge(Node* hole, Node* outerNode) {
    Node*  p  = outerNode;
    double hx = hole->x;
    double hy = hole->y;
    double qx = -infinity;            // literal -inf, not -DBL_MAX
    Node*  m  = nullptr;

    // ---- loop 1: leftward ray cast ----
    do {
        if (hy <= p->y && hy >= p->next->y && p->next->y != p->y) {
            double x = p->x + (hy - p->y) * (p->next->x - p->x) / (p->next->y - p->y);
            if (x <= hx && x > qx) {
                qx = x;
                m  = (p->x < p->next->x) ? p : p->next;
                if (x == hx) return m;        // hole touches outer segment: EARLY RETURN
            }
        }
        p = p->next;
    } while (p != outerNode);

    if (!m) return nullptr;

    // ---- loop 2: minimum-tangent selection ----
    const Node* stop = m;                 // SNAPSHOT of the initial m
    double tanMin = +infinity;
    double mx = m->x;                     // SNAPSHOT, never updated when m moves
    double my = m->y;

    p = m;                                // starts AT m (do/while), so m itself is tested
    do {
        if (hx >= p->x && p->x >= mx && hx != p->x &&
            pointInTriangle(hy < my ? hx : qx, hy,
                            mx,                my,
                            hy < my ? qx : hx, hy,
                            p->x,              p->y)) {

            double tan = std::abs(hy - p->y) / (hx - p->x);

            if (locallyInside(p, hole) &&
                (tan < tanMin || (tan == tanMin && (p->x > m->x || sectorContainsSector(m, p))))) {
                m = p;
                tanMin = tan;
            }
        }
        p = p->next;
    } while (p != stop);

    return m;
}
```
Load-bearing details:
* Loop 1 traverses **forward from `outerNode`**, testing `outerNode` first. Only downward edges qualify (`<=` on the from-endpoint, `>=` on the to-endpoint). `x > qx` is **strict**, so among segments producing the identical `x`, the **first reached from the anchor** wins → the anchor identity is observable.
* Ray x expression: multiply, then divide, then add `p->x`.
* `m = p->x < p->next->x ? p : p->next` — strict `<`; vertical edge (tie) picks `p->next`.
* `if (x == hx) return m;` sits **inside** the accept block, **after** `qx = x` and **after** `m` is assigned. There is **no** post-loop `if (hx == qx) return m->prev;` in 2.2.4.
* Loop 2 gate uses the **frozen** `mx`; the tie-break uses the **live** `m->x`. Replicate both.
* `locallyInside(p, hole)` is evaluated **first** in 2.2.x (cost-only difference).
* The `sectorContainsSector` arm is **UNGATED** in the C++ port (no `p->x == m->x &&` prefix). JS has the gate; C++ does not.

### 1.19 `eliminateHole`  — 2.2.3/2.2.4 form (V3)

```
Node* eliminateHole(Node* hole, Node* outerNode) {
    Node* bridge = findHoleBridge(hole, outerNode);
    if (!bridge) return outerNode;

    Node* bridgeReverse = splitPolygon(bridge, hole);   // arg order: (outer node, hole node)

    // filter collinear points around the cuts
    filterPoints(bridgeReverse, bridgeReverse->next);   // bridgeReverse FIRST
    // Check if input node was removed by the filtering
    return filterPoints(bridge, bridge->next);          // return value = new outer anchor
}
```

### 1.20 `eliminateHoles`

```
Node* eliminateHoles(const Polygon& points, Node* outerNode) {
    const size_t len = points.size();

    queue.clear();
    for (size_t i = 1; i < len; i++) {                 // ASCENDING ring order
        Node* list = linkedList(points[i], false);     // clockwise = false
        if (list) {
            if (list == list->next) list->steiner = true;   // 1-node hole => Steiner
            queue.push_back(getLeftmost(list));
        }
    }

    std::sort(queue.begin(), queue.end(),
              [](const Node* a, const Node* b) { return a->x < b->x; });   // x ONLY

    for (size_t i = 0; i < queue.size(); i++)
        outerNode = eliminateHole(queue[i], outerNode);

    return outerNode;
}
```
All holes are linked (and thus numbered) **before** the sort, so node indices are unaffected by hole ordering. There is **no** second `filterPoints` in this loop (that is the pre-2.2.3 form).

### 1.21 `zOrder`

```
int32_t zOrder(const double x_, const double y_) {
    int32_t x = static_cast<int32_t>((x_ - minX) * inv_size);   // MULTIPLY by reciprocal
    int32_t y = static_cast<int32_t>((y_ - minY) * inv_size);

    x = (x | (x << 8)) & 0x00FF00FF;
    x = (x | (x << 4)) & 0x0F0F0F0F;
    x = (x | (x << 2)) & 0x33333333;
    x = (x | (x << 1)) & 0x55555555;

    y = (y | (y << 8)) & 0x00FF00FF;
    y = (y | (y << 4)) & 0x0F0F0F0F;
    y = (y | (y << 2)) & 0x33333333;
    y = (y | (y << 1)) & 0x55555555;

    return x | (y << 1);
}
```
Truncating cast (toward zero, == JS `|0`). The `32767.` constant lives in `operator()`, **not** here. Both axes share one isotropic `inv_size`.

### 1.22 `sortLinked` (Simon Tatham bottom-up merge sort on the z-chain)

```
Node* sortLinked(Node* list) {
    Node *p, *q, *e, *tail;
    int i, numMerges, pSize, qSize;
    int inSize = 1;

    for (;;) {
        p = list; list = nullptr; tail = nullptr; numMerges = 0;

        while (p) {
            numMerges++;
            q = p; pSize = 0;
            for (i = 0; i < inSize; i++) { pSize++; q = q->nextZ; if (!q) break; }
            qSize = inSize;

            while (pSize > 0 || (qSize > 0 && q)) {
                if      (pSize == 0)          { e = q; q = q->nextZ; qSize--; }
                else if (qSize == 0 || !q)    { e = p; p = p->nextZ; pSize--; }
                else if (p->z <= q->z)        { e = p; p = p->nextZ; pSize--; }
                else                          { e = q; q = q->nextZ; qSize--; }

                if (tail) tail->nextZ = e; else list = e;
                e->prevZ = tail;
                tail = e;
            }
            p = q;
        }
        tail->nextZ = nullptr;
        if (numMerges <= 1) return list;
        inSize *= 2;
    }
}
```
`p->z <= q->z` makes it **stable**; z-ties are common (duplicate coords, same 15-bit cell), so stability is load-bearing.

### 1.23 `indexCurve`

```
void indexCurve(Node* start) {
    assert(start);
    Node* p = start;
    do {
        p->z = p->z ? p->z : zOrder(p->x, p->y);   // reuse already-computed z
        p->prevZ = p->prev;
        p->nextZ = p->next;
        p = p->next;
    } while (p != start);

    p->prevZ->nextZ = nullptr;    // p == start here: cut the circle
    p->prevZ = nullptr;

    sortLinked(p);                // return value DELIBERATELY DISCARDED
}
```
Pre-sort sequence is `start, start->next, ..., start->prev` — combined with the stable sort, **the identity of `start` determines the post-sort order of equal-z nodes**, hence the search order in `isEarHashed`.

### 1.24 `isEar`

```
bool isEar(Node* ear) {
    const Node* a = ear->prev;
    const Node* b = ear;
    const Node* c = ear->next;

    if (area(a, b, c) >= 0) return false;      // reflex, can't be an ear

    Node* p = ear->next->next;
    while (p != ear->prev) {
        if (pointInTriangle(a->x, a->y, b->x, b->y, c->x, c->y, p->x, p->y) &&
            area(p->prev, p, p->next) >= 0) return false;
        p = p->next;
    }
    return true;
}
```
Scan is exactly the strictly-interior vertices: from `ear->next->next` forward, stopping at `ear->prev`. Both rejections use `>= 0`. Convex intruders are ignored — only reflex/collinear intruders veto. (No coordinate bbox pre-filter; see Switch #12 — adding one is output-neutral.)

### 1.25 `isEarHashed`

```
bool isEarHashed(Node* ear) {
    const Node* a = ear->prev;
    const Node* b = ear;
    const Node* c = ear->next;

    if (area(a, b, c) >= 0) return false;

    // triangle bbox; min & max are calculated like this for speed
    const double minTX = std::min<double>(a->x, std::min<double>(b->x, c->x));
    const double minTY = std::min<double>(a->y, std::min<double>(b->y, c->y));
    const double maxTX = std::max<double>(a->x, std::max<double>(b->x, c->x));
    const double maxTY = std::max<double>(a->y, std::max<double>(b->y, c->y));

    const int32_t minZ = zOrder(minTX, minTY);      // computed FIRST
    const int32_t maxZ = zOrder(maxTX, maxTY);      // computed SECOND

    Node* p = ear->prevZ;
    Node* n = ear->nextZ;

    while (p && p->z >= minZ && n && n->z <= maxZ) {
        if (p->x >= minTX && p->x <= maxTX && p->y >= minTY && p->y <= maxTY &&
            p != ear->prev && p != ear->next &&
            pointInTriangle(a->x,a->y,b->x,b->y,c->x,c->y,p->x,p->y) &&
            area(p->prev, p, p->next) >= 0) return false;
        p = p->prevZ;

        if (n->x >= minTX && n->x <= maxTX && n->y >= minTY && n->y <= maxTY &&
            n != ear->prev && n != ear->next &&
            pointInTriangle(a->x,a->y,b->x,b->y,c->x,c->y,n->x,n->y) &&
            area(n->prev, n, n->next) >= 0) return false;
        n = n->nextZ;
    }

    while (p && p->z >= minZ) {          // drain prevZ side
        if (p != ear->prev && p != ear->next &&
            p->x >= minTX && p->x <= maxTX && p->y >= minTY && p->y <= maxTY &&
            pointInTriangle(a->x,a->y,b->x,b->y,c->x,c->y,p->x,p->y) &&
            area(p->prev, p, p->next) >= 0) return false;
        p = p->prevZ;
    }

    while (n && n->z <= maxZ) {          // drain nextZ side
        if (n != ear->prev && n != ear->next &&
            n->x >= minTX && n->x <= maxTX && n->y >= minTY && n->y <= maxTY &&
            pointInTriangle(a->x,a->y,b->x,b->y,c->x,c->y,n->x,n->y) &&
            area(n->prev, n, n->next) >= 0) return false;
        n = n->nextZ;
    }

    return true;
}
```
**Both z bounds inclusive.** The candidate SET scanned (all `prevZ` nodes with `z >= minZ` ∪ all `nextZ` nodes with `z <= maxZ`) is identical to the older two-sequential-loops form, and the result is an OR over that set, so the two shapes are **output-identical** (Disagreement D3). The coordinate-bbox conjunct is a conservative pre-filter and is likewise output-neutral. Keep the `p != ear->prev && p != ear->next` guards (JS 3.0 drops them — do not).

### 1.26 `cureLocalIntersections`

```
Node* cureLocalIntersections(Node* start) {
    Node* p = start;
    do {
        Node* a = p->prev;
        Node* b = p->next->next;

        if (!equals(a, b) && intersects(a, p, p->next, b) &&
            locallyInside(a, b) && locallyInside(b, a)) {

            indices.emplace_back(a->i);
            indices.emplace_back(p->i);
            indices.emplace_back(b->i);      // p->next is NEVER emitted, only deleted

            removeNode(p);
            removeNode(p->next);             // p->next re-read AFTER removeNode(p);
                                             //   do NOT hoist a `Node* pn = p->next;`
            p = start = b;
        }
        p = p->next;
    } while (p != start);

    return filterPoints(p);                  // p == start at exit; equivalent either way
}
```
Guard order exactly: `!equals(a,b)` → `intersects(a, p, p->next, b)` → `locallyInside(a,b)` → `locallyInside(b,a)`. Note the first `intersects` argument is `a = p->prev`, not `p`.

### 1.27 `splitEarcut`

```
void splitEarcut(Node* start) {
    Node* a = start;
    do {
        Node* b = a->next->next;
        while (b != a->prev) {
            if (a->i != b->i && isValidDiagonal(a, b)) {
                Node* c = splitPolygon(a, b);

                a = filterPoints(a, a->next);      // two-arg form
                c = filterPoints(c, c->next);

                earcutLinked(a);                   // a-half FIRST, pass defaults to 0
                earcutLinked(c);                   // then c-half
                return;                            // first valid diagonal wins; no retry
            }
            b = b->next;
        }
        a = a->next;
    } while (a != start);
}
```
Both loops forward; inner starts at `a->next->next` and stops before `a->prev`. Cheap `a->i != b->i` first. Silent give-up if no diagonal exists (those vertices are simply never triangulated). Because both recursive calls use pass 0, `indexCurve` re-runs on each half when hashing is on.

### 1.28 `earcutLinked`

```
void earcutLinked(Node* ear, int pass = 0) {
    if (!ear) return;

    if (!pass && hashing) indexCurve(ear);

    Node* stop = ear;
    Node* prev;
    Node* next;

    while (ear->prev != ear->next) {
        prev = ear->prev;
        next = ear->next;                        // both latched BEFORE the ear test

        if (hashing ? isEarHashed(ear) : isEar(ear)) {
            indices.emplace_back(prev->i);       // 1st
            indices.emplace_back(ear->i);        // 2nd
            indices.emplace_back(next->i);       // 3rd

            removeNode(ear);

            // skipping the next vertex leads to less sliver triangles
            ear  = next->next;
            stop = next->next;
            continue;
        }

        ear = next;

        if (ear == stop) {
            if      (!pass)      earcutLinked(filterPoints(ear), 1);
            else if (pass == 1) { ear = cureLocalIntersections(filterPoints(ear));
                                  earcutLinked(ear, 2); }
            else if (pass == 2)  splitEarcut(ear);
            break;                               // ALWAYS breaks, whichever branch ran
        }
    }
}
```
* Pass 0 fallback passes `filterPoints(ear)` **directly** as the argument (no intermediate assignment to `ear`). Pass 1 **does** assign before recursing.
* `hashing` (not `pass`) selects the ear test, so passes 1 and 2 still use `isEarHashed`.
* No iteration counter / bailout anywhere.

### 1.29 `operator()`

```
void operator()(const Polygon& points) {
    indices.clear();
    vertices = 0;
    if (!points.size()) return;

    double x, y;
    int threshold = 80;
    std::size_t len = 0;

    for (size_t i = 0; threshold >= 0 && i < points.size(); i++) {
        threshold -= static_cast<int>(points[i].size());
        len += points[i].size();                  // deliberately under-counts (loop short-circuits)
    }

    nodes.reset(len * 3 / 2);                     // allocation only; no output effect
    indices.reserve(len + points[0].size());      // allocation only

    Node* outerNode = linkedList(points[0], true);
    if (!outerNode || outerNode->prev == outerNode->next) return;
    // NOTE: no filterPoints on the outer ring here.

    if (points.size() > 1) outerNode = eliminateHoles(points, outerNode);

    hashing = threshold < 0;                      // strictly MORE than 80 total verts
    if (hashing) {
        Node* p = outerNode->next;                // walks the MERGED ring (holes included!)
        minX = maxX = outerNode->x;
        minY = maxY = outerNode->y;
        do {
            x = p->x; y = p->y;
            minX = std::min<double>(minX, x);
            minY = std::min<double>(minY, y);
            maxX = std::max<double>(maxX, x);
            maxY = std::max<double>(maxY, y);
            p = p->next;
        } while (p != outerNode);

        inv_size = std::max<double>(maxX - minX, maxY - minY);
        inv_size = inv_size != .0 ? (32767. / inv_size) : .0;   // two statements, one variable
    }

    earcutLinked(outerNode);                      // pass = 0

    nodes.clear();
}
```
The bbox is computed **after** `eliminateHoles`, over the merged linked list — a genuine C++-vs-JS divergence (JS uses the raw outer-ring slice). Do not "fix" it.

### 1.30 `mapbox::earcut` (free function)

```
template <typename N = uint32_t, typename Polygon>
std::vector<N> earcut(const Polygon& poly) {
    mapbox::detail::Earcut<N> earcut;
    earcut(poly);
    return std::move(earcut.indices);
}
```

